?><!doctype html><html><head><?php include('links.php');?><title>Alumni Donations</title><style>:root{--n:#102b4b;--t:#08766f;--p:#f4f7fb;--l:#dce5ed}*{box-sizing:border-box}body{margin:0;background:var(--p);color:#1e293b;font:15px Arial,sans-serif}.wrap{max-width:1200px;margin:auto;padding:30px 18px 60px}.hero{background:linear-gradient(120deg,var(--n),var(--t));color:#fff;border-radius:18px;padding:29px}.hero h1{font:600 30px Georgia,serif;margin:5px 0}.hero p{margin:0;color:#dbeaf0}.back{display:inline-block;margin-top:13px;padding:10px 13px;border-radius:8px;background:#fff;color:var(--n);text-decoration:none;font-weight:bold}.stat{margin-top:18px;background:#fff;border:1px solid var(--l);border-radius:15px;padding:20px}.stat span{color:#64748b;font-size:13px}.stat strong{display:block;font-size:30px;color:var(--n);margin-top:5px}.panel{margin-top:18px;background:#fff;border:1px solid var(--l);border-radius:15px;padding:20px;overflow:auto}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:12px;border-bottom:1px solid #e7edf2;font-size:13px;white-space:nowrap}th{background:#eff5f8;color:var(--n)}.success{color:#08766f;font-weight:bold}.failed{color:#ae3333;font-weight:bold}</style></head><body><main class="wrap"><section class="hero"><small>AYISEC ALUMNI ADMINISTRATION</small><h1>Alumni donations</h1><p>Verified donation payments processed through the AYISEC Paystack platform.</p><a class="back" href="alumni-hub.php">← Alumni Hub</a></section><section class="stat"><span>Successful Alumni donations</span><strong>GH₵ <?php echo number_format((float)($summary['total']??0),2);?></strong><small><?php echo number_format((int)($summary['donations']??0));?> completed payment(s)</small></section><section class="panel"><table><thead><tr><th>Alumnus</th><th>Year</th><th>Amount</th><th>Purpose</th><th>Status</th><th>Reference</th><th>Date</th></tr></thead><tbody><?php if($payments&&mysqli_num_rows($payments)>0){while($row=mysqli_fetch_assoc($payments)){?><tr><td><?php echo alumni_safe($row['fullname']);?></td><td><?php echo alumni_safe($row['graduationyear']);?></td><td><?php echo alumni_safe($row['currency'].' '.number_format((float)$row['amount'],2));?></td><td><?php echo alumni_safe($row['donationpurpose']);?></td><td class="<?php echo $row['status']==='success'?'success':'failed';?>"><?php echo alumni_safe(ucfirst($row['status']));?></td><td><?php echo alumni_safe($row['referenceid']);?></td><td><?php echo alumni_safe(date('d M Y, g:i a',strtotime($row['paidat']?:$row['createdat'])));?></td></tr><?php }}else{?><tr><td colspan="7">No Alumni donation payments have been started yet.</td></tr><?php }?></tbody></table></section></main></body></html>
